    if(this.buffer.length * b >= T) this.rebuild();
  }
  connected(u,v){
    return this.F.find(u) === this.F.find(v) || 
           this.searchResidual(u,v);
  }
  rebuild(){
    // merge buffered edges into compact structure
    // amortized O((n+mb)/B) I/Os
  }
